%[text] # Aufgabe 2.4: Gerade mit Bresenham Algorithmus
%%
%[text] ## a) Koordinaten der Linie berechnen
[xCoords, yCoords] = myBresenham(200, 200, 400, 400);

disp([xCoords(1:5); yCoords(1:5)]) %[output:6a83262b]
%%
%[text] ## b) Linie rot ins Bild einzeichnen
bild = imread('TestbildFernseher.jpg');

for i = 1:length(xCoords)
    x = xCoords(i);
    y = yCoords(i);
    bild(y-1:y+1, x-1:x+1, 1) = 255;
    bild(y-1:y+1, x-1:x+1, 2) = 0;
    bild(y-1:y+1, x-1:x+1, 3) = 0;
end

figure %[output:779586d6]
imshow(bild) %[output:779586d6]
title('Rote Linie mit Bresenham') %[output:779586d6]
%%
%[text] Test in alle Richtungen (Stern):
bild2 = zeros(101, 101, 3, 'uint8');
ziele = [100 50; 100 1; 50 1; 1 1; 1 50; 1 100; 50 100; 100 100; 90 20; 20 10];

for k = 1:size(ziele, 1)
    [xs, ys] = myBresenham(50, 50, ziele(k,1), ziele(k,2));
    for i = 1:length(xs)
        bild2(ys(i), xs(i), 1) = 255;
    end
end

figure %[output:1598e8a5]
imshow(bild2, 'InitialMagnification', 400) %[output:1598e8a5]
title('Linien in alle Richtungen') %[output:1598e8a5]
%%
%[text] ## Funktion
function [xCoords, yCoords] = myBresenham(xStart, yStart, xEnd, yEnd)
    dx =  abs(xEnd - xStart);
    dy = -abs(yEnd - yStart);
    sx = sign(xEnd - xStart);
    sy = sign(yEnd - yStart);
    fehler = dx + dy;

    x = xStart;
    y = yStart;
    xCoords = x;
    yCoords = y;

    while x ~= xEnd || y ~= yEnd
        e2 = 2 * fehler;
        if e2 >= dy
            fehler = fehler + dy;
            x = x + sx;
        end
        if e2 <= dx
            fehler = fehler + dx;
            y = y + sy;
        end
        xCoords(end+1) = x;
        yCoords(end+1) = y;
    end
end

